initFromHostname(hostname, username, type, customDetails) {
  if (typeof customDetails == "undefined") {
    customDetails = null;
  }

  const overridePrefEnabled = Services.prefs.getBoolPref(
    "experimental.mail.ews.overrideOAuth.enabled",
    false
  );

  const doOverrides =
    overridePrefEnabled && customDetails && customDetails.useCustomDetails;

  const details = doOverrides
    ? this._getDetailsWithOverrides(hostname, username, type, customDetails)
    : OAuth2Providers.getHostnameDetails(hostname, type, username);

  if (!details) {
    return false;
  }

  const { issuer, allScopes, requiredScopes } = details;

// For Microsoft Exchange servers. Optional.  Bug 2018801 will consolidate
// these into a single url distinguished by the server type.
url: null,
owaURL: null,
exchangeURL: null,
easURL: null,
// Optional custom OAuth details for Exchange servers.
oauthSettings: null,

function applyExchangeOAuthSettings(incomingServer, incomingConfig) {
  if (
    !incomingConfig.oauthSettings?.useCustomDetails ||
    !["ews", "graph"].includes(incomingConfig.type)
  ) {
    return;
  }

  const exchangeServer = incomingServer.QueryInterface(
    Ci.IExchangeIncomingServer
  );
  exchangeServer.exchangeOverrideOAuthDetails = true;
  exchangeServer.exchangeApplicationId = incomingConfig.oauthSettings.clientId;
  exchangeServer.exchangeTenantId = incomingConfig.oauthSettings.tenant;
